{
  "definition_simple": "店や倉庫にある品物のこと。",
  "definition_standard": "商品や材料などが、売るためまたは使うために保管されていること。また、その品物。",
  "pos": "n",
  "semantic_class": "abstract",
  "sentences": [
    {
      "tier": "T1",
      "text": "在庫があります。"
    },
    {
      "tier": "T1",
      "text": "在庫を確認します。"
    },
    {
      "tier": "T2",
      "text": "この商品は在庫が少ないです。"
    },
    {
      "tier": "T2",
      "text": "在庫の数を数えてください。"
    },
    {
      "tier": "T3",
      "text": "現在、こちらのサイズは在庫を切らしております。"
    },
    {
      "tier": "T3",
      "text": "オンラインショップで在庫状況をチェックする。"
    },
    {
      "tier": "T4",
      "text": "新製品の発売に伴い、旧型の在庫処分セールを実施します。"
    },
    {
      "tier": "T4",
      "text": "倉庫の在庫管理を徹底し、ロスの削減に努める。"
    },
    {
      "tier": "T5",
      "text": "需要の急増により、メーカーの在庫が完全に払底した。"
    },
    {
      "tier": "T6",
      "text": "過剰な在庫の抱え込みは、企業のキャッシュフローを圧迫する主要因となる。"
    }
  ],
  "morphological_forms": [],
  "morphology_wrong_forms": [],
  "primary_collocate": "在庫切れ",
  "collocation_distractors": [
    {
      "word": "在庫走",
      "reason": "「走」という漢字は在庫の文脈では使われず、熟語として成立しないため。"
    },
    {
      "word": "在庫見",
      "reason": "名詞の連続として不自然であり、一般的な日本語のコロケーションとして定着していないため。"
    },
    {
      "word": "在庫歩",
      "reason": "意味的なつながりがなく、このような複合語は日本語に存在しないため。"
    }
  ],
  "collocation_wrong_collocate": "在庫不足",
  "cloze_distractors": [
    {
      "word": "存在",
      "reason": "「存在」は人や物がそこにあることを指すが、商品などの保管されている量や状況を表す文脈には合わないため。"
    },
    {
      "word": "収蔵",
      "reason": "「収蔵」は美術品や資料などを博物館などにしまうことを指し、一般的な商品の商取引の文脈には適さないため。"
    },
    {
      "word": "容量",
      "reason": "「容量」は入れ物に入る体積や容積を意味し、商品の有無や数量を表す「在庫」の代わりにはならないため。"
    }
  ],
  "discrimination_wrong_sentences": [
    {
      "sentence": "昨日、新しい在庫を食べました。",
      "reason": "「在庫」は商品や物品を指すため、「食べる」という動作の直接の目的語にはできない。"
    },
    {
      "sentence": "彼の在庫はとても親切です。",
      "reason": "「在庫」は物に対して使われる名詞であり、人柄を表す「親切」という形容動詞とは一緒に使えない。"
    },
    {
      "sentence": "空にたくさんの在庫が飛んでいます。",
      "reason": "「在庫」は倉庫や店舗で保管されている商品を指し、空を飛ぶ鳥や飛行機などの対象には使えない。"
    }
  ],
  "spot_incorrect": {
    "sentence": "この本は人気があるので、すぐに在庫がなくなりました。",
    "error_description": "文法的な誤りはないが、自然なビジネス表現としては「在庫を切らしました」や「在庫が切れました」とする方がより適切である。",
    "corrected_version": "この本は人気があるので、すぐに在庫が切れました。"
  },
  "word_family_forms": [
    {
      "form": "在庫する",
      "pos": "verb",
      "definition": "商品を倉庫などに保管しておく。"
    },
    {
      "form": "在庫品",
      "pos": "noun",
      "definition": "実際に倉庫や店舗にある品物。"
    }
  ],
  "word_family_fake_forms": [
    {
      "form": "在庫化する",
      "pos": "verb",
      "reason": "「在庫にする」という表現はあるが、「在庫化する」という動詞は一般的に使われない。"
    },
    {
      "form": "在庫み",
      "pos": "noun",
      "reason": "形容詞の語幹につく接尾辞「み」が名詞についており、形態論的に不自然である。"
    },
    {
      "form": "在庫的",
      "pos": "adjective",
      "reason": "性質を表す「的」がつくような概念の言葉ではないため。"
    }
  ],
  "syn_ant_candidates": [
    {
      "word": "ストック",
      "type": "synonym"
    },
    {
      "word": "蔵置",
      "type": "synonym"
    },
    {
      "word": "品切れ",
      "type": "antonym"
    }
  ],
  "particle_candidates": [
    {
      "particle": "の",
      "correct": true,
      "explanation": "「在庫の確認」のように、名詞と名詞をつないで所有や関連を表すのに最も適切な粒子です。"
    },
    {
      "particle": "を",
      "correct": false,
      "explanation": "「を」は動作の対象を示しますが、ここでは後ろに別の名詞（確認）が続いているため不適切です。"
    },
    {
      "particle": "に",
      "correct": false,
      "explanation": "「に」は場所や方向を示し、「在庫に確認」とすると意味が通らなくなります。"
    },
    {
      "particle": "で",
      "correct": false,
      "explanation": "「で」は手段や場所を表しますが、「在庫で確認」では文脈に合いません。"
    }
  ]
}
